// ❌ 코드에 값 (절대 금지. 역사에 박힘)
const apiKey = 'sk_live_abc123...';

// ✅ 환경에서 읽기 (값은 코드 밖)
const apiKey = process.env.API_KEY;
if (!apiKey) throw new Error('API_KEY 환경변수가 없습니다');

// .env (로컬, .gitignore 에 반드시 추가)
//   API_KEY=sk_live_abc123...
// .env.example (커밋 O. 값 없이 키 이름만, 팀 안내용)
//   API_KEY=
// .gitignore
//   .env

// ❌ 헤더를 통째로 로그. authorization 토큰이 그대로 찍힘
logger.info({ event: 'api_call', url, headers });

// ✅ 민감 필드를 마스킹한 뒤 로그
logger.info({ event: 'api_call', url,
  headers: { ...headers, authorization: '[redacted]' } });

// 로깅 라이브러리의 redact 설정 (pino 예)
const logger = pino({
  redact: ['req.headers.authorization', 'req.headers.cookie',
           '*.password', '*.token', '*.secret']   // 자동 마스킹
});
